/* @lc app=leetcode id=3305 lang=kotlin */ class Solution { fun up(cnt: IntArray, st: IntArray, c: Char, d: Int) = if (c in "aeiou") cnt.set(c - 'a', cnt[c - 'a'] + d) else st.set(0, st[0] + d) fun f(word: String, k: Int): Long = IntArray(26).let { cnt -> IntArray(1).let { st -> word.indices.fold(0 to 0L) { (l, tot), r -> up(cnt, st, word[r], 1).let { generateSequence(l) { ll -> if ("aeiou".all { cnt[it - 'a'] > 0 } && st[0] >= k) up(cnt, st, word[ll], -1).let { ll + 1 } else null }.last().let { l2 -> l2 to tot + l2 } } }.second } } fun countOfSubstrings(word: String, k: Int): Int = (f(word, k) - f(word, k + 1)).toInt() }